from pathlib import Path
p=Path('prompt-bench.html')
s=p.read_text()

s=s.replace('return { name:"", kind:"person", marker:"", looks:"", wears:"", manner:"",\n           likes:"", avoid:"", photo:"", desc:"" };',
'''return { name:"", kind:"person", species:"", marker:"", looks:"", wears:"", manner:"",\n           likes:"", avoid:"", photo:"", desc:"" };''')

old='''    h += '<div class="who"><input type="text" data-k="name" placeholder="Name, slot '+(i+1)+'" value="'+esc(p.name)+'">'\n      + '<div class="kind">'\n      + '<label><input type="radio" name="kind'+i+'" data-k="kind" value="person"'+(p.kind!=="animal"?" checked":"")+'> Person</label>'\n      + '<label><input type="radio" name="kind'+i+'" data-k="kind" value="animal"'+(p.kind==="animal"?" checked":"")+'> Animal</label>'\n      + '</div></div>';'''
new='''    h += '<div class="who"><input type="text" data-k="name" placeholder="Name, slot '+(i+1)+'" value="'+esc(p.name)+'">'\n      + '<div class="kind">'\n      + '<label><input type="radio" name="kind'+i+'" data-k="kind" value="person"'+(p.kind!=="animal"?" checked":"")+'> Person</label>'\n      + '<label><input type="radio" name="kind'+i+'" data-k="kind" value="animal"'+(p.kind==="animal"?" checked":"")+'> Animal</label>'\n      + '</div>'\n      + (p.kind === "animal" ? '<input type="text" data-k="species" placeholder="Animal type, e.g. cat, parrot" value="'+esc(p.species||"")+'">' : '')\n      + '</div>';'''
if old not in s: raise SystemExit('renderPeople target not found')
s=s.replace(old,new)

old='''function dialText(d, v){\n  var stops = d.stops || [];\n  for(var i=0;i<stops.length;i++){\n    if(v <= stops[i].upTo) return fill(String(stops[i].text).replace(/\\{v\\}/g, v));\n  }\n  return stops.length ? fill(String(stops[stops.length-1].text).replace(/\\{v\\}/g, v)) : "";\n}\n\nfunction renderDials(){\n  var h = "";\n  MODEL.dials.forEach(function(d){\n    var min = (d.min === undefined ? 0 : d.min), max = (d.max === undefined ? 10 : d.max);\n    if(state.dials[d.id] === undefined) state.dials[d.id] = (d.value === undefined ? min : d.value);\n    h += '<div class="dial"><div class="row"><label for="d_'+esc(d.id)+'">'+esc(d.label)+'</label>'\n      +  '<output id="o_'+esc(d.id)+'"></output></div>'\n      +  '<input type="range" id="d_'+esc(d.id)+'" min="'+min+'" max="'+max+'" step="1" value="'+state.dials[d.id]+'">'\n      +  '<div class="ends"><span>'+esc(d.lo===undefined?min:d.lo)+'</span><span>'+esc(d.hi===undefined?max:d.hi)+'</span></div></div>';\n  });\n  el("dials").innerHTML = h;\n  MODEL.dials.forEach(function(d){\n    var input = el("d_"+d.id);\n    if(!input) return;\n    var show = function(){\n      var v = parseInt(input.value,10);\n      if(isNaN(v)) v = (d.value === undefined ? (d.min === undefined ? 0 : d.min) : d.value);\n      state.dials[d.id] = v;\n      el("o_"+d.id).textContent = dialText(d, v);\n    };\n    input.addEventListener("input", function(){ show(); saveState(); });\n    show();\n  });\n}\n'''
new='''function animalSpecies(p){\n  if(!p || p.kind !== "animal") return "person";\n  var explicit = String(p.species || "").trim().toLowerCase();\n  if(explicit) return explicit;\n  var hay = [p.name, p.looks, p.marker, p.desc].join(" ").toLowerCase();\n  var known = [\n    "parrot","cockatoo","budgie","macaw","canary","finch","sparrow","pigeon","crow","raven","eagle","hawk","falcon","owl","chicken","duck","goose","turkey","penguin","swan","bird",\n    "snake","lizard","gecko","iguana","crocodile","alligator","turtle","tortoise","dragon","shark","salmon","trout","goldfish","koi","carp","fish",\n    "cow","dog","cat","horse","goat","sheep","rabbit","mouse","rat","hamster","guinea pig","pig","bear","fox","wolf","lion","tiger","leopard","cheetah","monkey","ape","gorilla","chimpanzee","giraffe","deer","moose","otter","ferret","donkey","zebra","camel","alpaca","llama","bat",\n    "frog","toad","salamander","newt"\n  ];\n  for(var i=0;i<known.length;i++){\n    if(new RegExp("\\\\b"+known[i].replace(/[-/\\\\^$*+?.()|[\\]{}]/g,"\\\\$&")+"\\\\b").test(hay)) return known[i];\n  }\n  return "animal";\n}\n\nfunction coveringFor(p){\n  if(!p || p.kind !== "animal") return "hair";\n  var species = animalSpecies(p);\n  var birds = "parrot cockatoo budgie macaw canary finch sparrow pigeon crow raven eagle hawk falcon owl chicken duck goose turkey penguin swan bird".split(" ");\n  var scales = "snake lizard gecko iguana crocodile alligator turtle tortoise dragon shark salmon trout goldfish koi carp fish".split(" ");\n  var hair = "cow dog cat horse goat sheep rabbit mouse rat hamster pig bear fox wolf lion tiger leopard cheetah monkey ape gorilla chimpanzee giraffe deer moose otter ferret donkey zebra camel alpaca llama bat".split(" ");\n  var skin = "frog toad salamander newt".split(" ");\n  if(birds.indexOf(species) > -1) return "feathers";\n  if(scales.indexOf(species) > -1) return "scales";\n  if(hair.indexOf(species) > -1) return "hair";\n  if(skin.indexOf(species) > -1) return "skin";\n  return (species && species !== "animal") ? species + " covering" : "animal covering";\n}\n\nfunction dialLocalFill(text, ctx){\n  ctx = ctx || {};\n  return fill(String(text).replace(/\\{(name|species|covering|selected|selection|slot)\\}/g, function(whole, key){\n    return ctx[key] === undefined ? whole : ctx[key];\n  }));\n}\n\nfunction selectedCategoryItems(key){\n  var mid = currentMasterId(), out = [];\n  MODEL.categories.forEach(function(c){\n    if(c.key !== key) return;\n    c.items.forEach(function(it){ if(state.on[it.n] && suits(it, mid)) out.push(it); });\n  });\n  return out;\n}\n\nfunction selectionLabel(text){\n  var clean = String(text || "").replace(/\\s+/g," ").trim();\n  var first = clean.split(/[.;:]/)[0].trim() || clean;\n  return first.length > 58 ? first.slice(0,55).replace(/\\s+\\S*$/," GONE") + "…" : first;\n}\n\nfunction dialInstances(){\n  var out = [];\n  MODEL.dials.forEach(function(d){\n    var minSelected = (d.minSelected === undefined ? 1 : d.minSelected);\n    if(d.whenCategory && selectedCategoryItems(d.whenCategory).length < minSelected) return;\n\n    if(d.repeatFor === "cast"){\n      activeCast().forEach(function(p, i){\n        var name = (p.name || "").trim() || "Character " + (i+1);\n        var species = animalSpecies(p);\n        out.push({ def:d, id:d.id+"::cast:"+(i+1), ctx:{\n          name:name, species:species, covering:coveringFor(p), slot:String(i+1)\n        }});\n      });\n      return;\n    }\n\n    if(d.repeatFor === "selected"){\n      var items = selectedCategoryItems(d.category || "");\n      if(items.length < minSelected) return;\n      items.forEach(function(it){\n        out.push({ def:d, id:d.id+"::selected:"+it.n, ctx:{\n          selected:fill(it.t), selection:selectionLabel(fill(it.t)), slot:String(it.n)\n        }});\n      });\n      return;\n    }\n\n    out.push({def:d, id:d.id, ctx:{}});\n  });\n  return out;\n}\n\nfunction dialText(inst, v){\n  var d = inst.def || inst, stops = d.stops || [], ctx = inst.ctx || {};\n  for(var i=0;i<stops.length;i++){\n    if(v <= stops[i].upTo) return dialLocalFill(String(stops[i].text).replace(/\\{v\\}/g, v), ctx);\n  }\n  return stops.length ? dialLocalFill(String(stops[stops.length-1].text).replace(/\\{v\\}/g, v), ctx) : "";\n}\n\nfunction renderDials(){\n  var h = "", instances = dialInstances();\n  instances.forEach(function(inst){\n    var d = inst.def, min = (d.min === undefined ? 0 : d.min), max = (d.max === undefined ? 10 : d.max);\n    if(state.dials[inst.id] === undefined) state.dials[inst.id] = (d.value === undefined ? min : d.value);\n    h += '<div class="dial"><div class="row"><label for="d_'+esc(inst.id)+'">'+esc(dialLocalFill(d.label, inst.ctx))+'</label>'\n      +  '<output id="o_'+esc(inst.id)+'"></output></div>'\n      +  '<input type="range" id="d_'+esc(inst.id)+'" min="'+min+'" max="'+max+'" step="1" value="'+state.dials[inst.id]+'">'\n      +  '<div class="ends"><span>'+esc(dialLocalFill(d.lo===undefined?min:d.lo, inst.ctx))+'</span><span>'+esc(dialLocalFill(d.hi===undefined?max:d.hi, inst.ctx))+'</span></div></div>';\n  });\n  el("dials").innerHTML = h;\n  instances.forEach(function(inst){\n    var d = inst.def, input = el("d_"+inst.id);\n    if(!input) return;\n    var show = function(){\n      var v = parseInt(input.value,10);\n      if(isNaN(v)) v = (d.value === undefined ? (d.min === undefined ? 0 : d.min) : d.value);\n      state.dials[inst.id] = v;\n      el("o_"+inst.id).textContent = dialText(inst, v);\n    };\n    input.addEventListener("input", function(){ show(); saveState(); });\n    show();\n  });\n}\n'''
if old not in s: raise SystemExit('dial block target not found')
s=s.replace(old,new)

s=s.replace('''  state.castCount = parseInt(b.dataset.count,10);\n  saveState(); renderPeople(); renderGroups();''','''  state.castCount = parseInt(b.dataset.count,10);\n  saveState(); renderPeople(); renderGroups(); renderDials();''')
s=s.replace('''  if(e.target.dataset.k === "name"){ renderCounter(); renderGroups(); }''','''  if(e.target.dataset.k === "name" || e.target.dataset.k === "species"){ renderCounter(); renderGroups(); renderDials(); }''')
s=s.replace('''    state.cast[parseInt(card.dataset.i,10)].kind = e.target.value;\n    saveState();''','''    state.cast[parseInt(card.dataset.i,10)].kind = e.target.value;\n    saveState(); renderPeople(); renderDials();''')
s=s.replace('''    state.cast[parseInt(b.dataset.clearperson,10)] = blankPerson(); saveState(); renderPeople(); renderGroups();''','''    state.cast[parseInt(b.dataset.clearperson,10)] = blankPerson(); saveState(); renderPeople(); renderGroups(); renderDials();''')
s=s.replace('''  saveState(); renderPeople(); renderGroups();\n  note("Built in cast restored.");''','''  saveState(); renderPeople(); renderGroups(); renderDials();\n  note("Built in cast restored.");''')
s=s.replace('''  saveState(); renderPeople(); renderGroups();\n  note("Every slot emptied. The count is unchanged.");''','''  saveState(); renderPeople(); renderGroups(); renderDials();\n  note("Every slot emptied. The count is unchanged.");''')
s=s.replace('''  if(t && t.name === "master"){ _masterId = t.value; state.master = t.value; saveState(); renderGroups(); return; }''','''  if(t && t.name === "master"){ _masterId = t.value; state.master = t.value; saveState(); renderGroups(); renderDials(); return; }''')
s=s.replace('''    state.on[parseInt(t.dataset.n,10)] = t.checked;\n    updateCounts(); saveState();''','''    state.on[parseInt(t.dataset.n,10)] = t.checked;\n    updateCounts(); saveState(); renderDials();''')
s=s.replace('''    MODEL.dials.forEach(function(d){\n      if(d.carryToFollowUp) lines.push("- " + dialText(d, state.dials[d.id]));\n    });''','''    dialInstances().forEach(function(inst){\n      if(inst.def.carryToFollowUp) lines.push("- " + dialText(inst, state.dials[inst.id]));\n    });''')
s=s.replace('''  if(MODEL.dials.length){\n    lines.push(""); lines.push("DIALS");\n    MODEL.dials.forEach(function(d){\n      var t = dialText(d, state.dials[d.id]);\n      if(t) lines.push(t);\n    });\n  }''','''  var dialList = dialInstances();\n  if(dialList.length){\n    lines.push(""); lines.push("DIALS");\n    dialList.forEach(function(inst){\n      var t = dialText(inst, state.dials[inst.id]);\n      if(t) lines.push(t);\n    });\n  }''')
s=s.replace('''    return { id:"p"+(i+1), name:p.name, kind:p.kind, marker:p.marker, looks:p.looks,\n             wears:p.wears, manner:p.manner, likes:p.likes, avoid:p.avoid };''','''    return { id:"p"+(i+1), name:p.name, kind:p.kind, species:p.species || "", marker:p.marker, looks:p.looks,\n             wears:p.wears, manner:p.manner, likes:p.likes, avoid:p.avoid };''')

if 'function dialInstances()' not in s or 'data-k="species"' not in s:
    raise SystemExit('dynamic slider markers missing after patch')
p.write_text(s)
